package com.compostedsoil;

enum CompostState
{
	NONE(0, 0.0d),
	COMPOST(0x341c00, 0.0d),
	SUPERCOMPOST(0x1a2617, 0.30d),
	ULTRACOMPOST(0x3c1a1a, 0.55d);

	private final int rgb;
	private final double shadowContrast;

	CompostState(int rgb, double shadowContrast)
	{
		this.rgb = rgb;
		this.shadowContrast = shadowContrast;
	}

	boolean isComposted()
	{
		return this != NONE;
	}

	int getRgb()
	{
		return rgb;
	}

	double getShadowContrast()
	{
		return shadowContrast;
	}

}

package com.compostedsoil;

import java.util.Set;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;

final class CompostStateStore
{
	private static final String CONFIG_KEY_PREFIX = "compoststate.v1.";
	private static final String RECORD_VERSION = "1";

	private final ConfigManager configManager;

	@Inject
	CompostStateStore(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	StoredCompost load(
		PatchKey patchKey)
	{
		if (!hasProfile())
		{
			return StoredCompost.absent();
		}

		String raw = configManager.getRSProfileConfiguration(
			CompostedSoilConfig.GROUP,
			configKey(patchKey));
		return parse(raw);
	}

	void save(
		Set<PatchKey> patchKeys,
		CompostState state,
		long revision)
	{
		if (!hasProfile() || patchKeys == null || state == null)
		{
			return;
		}

		String value = RECORD_VERSION
			+ "|" + state.name()
			+ "|" + Math.max(0L, revision);
		for (PatchKey patchKey : patchKeys)
		{
			configManager.setRSProfileConfiguration(
				CompostedSoilConfig.GROUP,
				configKey(patchKey),
				value);
		}
	}

	private boolean hasProfile()
	{
		return configManager.getRSProfileKey() != null;
	}

	static String configKey(PatchKey patchKey)
	{
		return CONFIG_KEY_PREFIX + patchKey;
	}

	static StoredCompost parse(String raw)
	{
		if (raw == null)
		{
			return StoredCompost.absent();
		}

		String[] fields = raw.split("\\|", -1);
		if (fields.length != 3 || !RECORD_VERSION.equals(fields[0]))
		{
			return StoredCompost.invalid();
		}

		CompostState state = parseState(fields[1]);
		if (state == null)
		{
			return StoredCompost.invalid();
		}

		try
		{
			long revision = Long.parseLong(fields[2]);
			return revision < 0L
				? StoredCompost.invalid()
				: StoredCompost.valid(state, revision);
		}
		catch (NumberFormatException ignored)
		{
			return StoredCompost.invalid();
		}
	}

	private static CompostState parseState(String raw)
	{
		if (raw == null)
		{
			return null;
		}

		try
		{
			return CompostState.valueOf(raw.trim());
		}
		catch (IllegalArgumentException ignored)
		{
			return null;
		}
	}

	static final class StoredCompost
	{
		private final boolean present;
		private final boolean valid;
		private final CompostState state;
		private final long revision;

		private StoredCompost(
			boolean present,
			boolean valid,
			CompostState state,
			long revision)
		{
			this.present = present;
			this.valid = valid;
			this.state = state;
			this.revision = revision;
		}

		private static StoredCompost absent()
		{
			return new StoredCompost(
				false,
				false,
				null,
				-1L);
		}

		private static StoredCompost invalid()
		{
			return new StoredCompost(
				true,
				false,
				null,
				-1L);
		}

		private static StoredCompost valid(
			CompostState state,
			long revision)
		{
			return new StoredCompost(
				true,
				true,
				state,
				revision);
		}

		boolean isPresent()
		{
			return present;
		}

		boolean isValid()
		{
			return valid;
		}

		CompostState getState()
		{
			return state;
		}

		long getRevision()
		{
			return revision;
		}
	}
}

