package com.compostedsoil;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Window;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.function.Predicate;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.components.ColorJButton;
import net.runelite.client.util.ColorUtil;

final class CompostedSoilConfigPanelSync
{
	private static final String PLUGIN_TITLE = "Composted Soil";
	private static final Map<String, String> FIELDS = createFields();

	private CompostedSoilConfigPanelSync()
	{
	}

	static void refreshOpenPanel(Map<String, Object> values)
	{
		if (values == null || values.isEmpty())
		{
			return;
		}

		Map<String, Object> pendingValues = new LinkedHashMap<>();
		for (Map.Entry<String, Object> entry : values.entrySet())
		{
			if (FIELDS.containsKey(entry.getKey()))
			{
				pendingValues.put(entry.getKey(), entry.getValue());
			}
		}
		if (pendingValues.isEmpty())
		{
			return;
		}

		SwingUtilities.invokeLater(() ->
		{
			for (Window window : Window.getWindows())
			{
				synchronize(window, pendingValues);
			}
		});
	}

	static int synchronize(Component root, Map<String, Object> values)
	{
		if (root == null || values == null || values.isEmpty())
		{
			return 0;
		}

		Container configPanel = findConfigPanel(root);
		if (configPanel == null)
		{
			return 0;
		}

		int synchronizedFields = 0;
		for (Map.Entry<String, Object> entry : values.entrySet())
		{
			String name = FIELDS.get(entry.getKey());
			if (name == null)
			{
				continue;
			}

			Container row = findRow(configPanel, name);
			if (row != null && updateControl(row, entry.getValue()))
			{
				synchronizedFields++;
			}
		}
		return synchronizedFields;
	}

	static boolean hasRegisteredField(String key)
	{
		return FIELDS.containsKey(key);
	}

	private static Container findConfigPanel(Component component)
	{
		if (component instanceof JLabel
			&& PLUGIN_TITLE.equals(((JLabel) component).getText()))
		{
			for (Container ancestor = component.getParent();
				ancestor != null;
				ancestor = ancestor.getParent())
			{
				if (containsAllFields(ancestor))
				{
					return ancestor;
				}
			}
		}

		if (!(component instanceof Container))
		{
			return null;
		}
		for (Component child : ((Container) component).getComponents())
		{
			Container configPanel = findConfigPanel(child);
			if (configPanel != null)
			{
				return configPanel;
			}
		}
		return null;
	}

	private static boolean containsAllFields(Container container)
	{
		for (String name : FIELDS.values())
		{
			if (findLabel(container, name) == null)
			{
				return false;
			}
		}
		return true;
	}

	private static JLabel findLabel(Component component, String text)
	{
		if (component instanceof JLabel
			&& text.equals(((JLabel) component).getText()))
		{
			return (JLabel) component;
		}
		if (!(component instanceof Container))
		{
			return null;
		}
		for (Component child : ((Container) component).getComponents())
		{
			JLabel label = findLabel(child, text);
			if (label != null)
			{
				return label;
			}
		}
		return null;
	}

	private static Container findRow(Component component, String name)
	{
		if (!(component instanceof Container))
		{
			return null;
		}

		Container container = (Container) component;
		for (Component child : container.getComponents())
		{
			if (child instanceof JLabel
				&& name.equals(((JLabel) child).getText()))
			{
				return container;
			}
		}
		for (Component child : container.getComponents())
		{
			Container row = findRow(child, name);
			if (row != null)
			{
				return row;
			}
		}
		return null;
	}

	private static boolean updateControl(Container row, Object value)
	{
		if (value instanceof Color)
		{
			ColorJButton colorButton = (ColorJButton) findDescendant(
				row,
				child -> child instanceof ColorJButton);
			if (colorButton == null)
			{
				return false;
			}

			Color color = (Color) value;
			colorButton.setColor(color);
			colorButton.setText(
				"#" + ColorUtil.colorToAlphaHexCode(color)
					.toUpperCase(Locale.ROOT));
			return true;
		}

		JComboBox<?> comboBox = (JComboBox<?>) findDescendant(
			row,
			child -> child instanceof JComboBox);
		if (comboBox == null)
		{
			return false;
		}

		Object item = findComboBoxItem(comboBox, value);
		if (item == null)
		{
			return false;
		}
		if (!Objects.equals(comboBox.getSelectedItem(), item))
		{
			comboBox.setSelectedItem(item);
		}
		return true;
	}

	private static Object findComboBoxItem(
		JComboBox<?> comboBox,
		Object value)
	{
		String expected = value instanceof Enum
			? ((Enum<?>) value).name()
			: String.valueOf(value);
		for (int index = 0; index < comboBox.getItemCount(); index++)
		{
			Object item = comboBox.getItemAt(index);
			if (Objects.equals(item, value)
				|| item instanceof Enum
					&& expected.equals(((Enum<?>) item).name()))
			{
				return item;
			}
		}
		return null;
	}

	private static Component findDescendant(
		Component component,
		Predicate<Component> predicate)
	{
		if (predicate.test(component))
		{
			return component;
		}
		if (!(component instanceof Container))
		{
			return null;
		}
		for (Component child : ((Container) component).getComponents())
		{
			Component match = findDescendant(child, predicate);
			if (match != null)
			{
				return match;
			}
		}
		return null;
	}

	private static Map<String, String> createFields()
	{
		Map<String, String> fields = new HashMap<>();
		fields.put(CompostedSoilConfig.PRESET, "Preset");
		fields.put(CompostedSoilConfig.COMPOST_COLOR, "Compost color");
		fields.put(
			CompostedSoilConfig.SUPERCOMPOST_COLOR,
			"Supercompost color");
		fields.put(
			CompostedSoilConfig.ULTRACOMPOST_COLOR,
			"Ultracompost color");
		return Collections.unmodifiableMap(fields);
	}
}

