@Slf4j
@PluginDescriptor(
	name = "Composted Soil",
	description = "Tints composted farming patches by compost type",
	tags = {"farming", "farm", "compost", "supercompost", "ultracompost", "soil", "patch", "plot", "immersive"}
)
public class CompostedSoilPlugin extends Plugin
{
	private static final Duration PENDING_TIMEOUT = Duration.ofSeconds(30);
	private static final String PRESET_STATE_KEY = "presetState";

	private static final Set<Integer> FARMING_VARBITS = Set.of(
		VarbitID.FARMING_TRANSMIT_A,
		VarbitID.FARMING_TRANSMIT_B,
		VarbitID.FARMING_TRANSMIT_C,
		VarbitID.FARMING_TRANSMIT_D,
		VarbitID.FARMING_TRANSMIT_E,
		VarbitID.FARMING_TRANSMIT_F,
		VarbitID.FARMING_TRANSMIT_G,
		VarbitID.FARMING_TRANSMIT_H,
		VarbitID.FARMING_TRANSMIT_I,
		VarbitID.FARMING_TRANSMIT_J,
		VarbitID.FARMING_TRANSMIT_K,
		VarbitID.FARMING_TRANSMIT_L,
		VarbitID.FARMING_TRANSMIT_M,
		VarbitID.FARMING_TRANSMIT_N,
		VarbitID.FARMING_TRANSMIT_O,
		VarbitID.FARMING_TRANSMIT_P,
		VarbitID.FARMING_TRANSMIT_A1,
		VarbitID.FARMING_TRANSMIT_A2,
		VarbitID.FARMING_TRANSMIT_B1,
		VarbitID.FARMING_TRANSMIT_B2,
		VarbitID.FARMING_TRANSMIT_C1,
		VarbitID.FARMING_TRANSMIT_C2,
		VarbitID.FARMING_TRANSMIT_D1,
		VarbitID.FARMING_TRANSMIT_D2,
		VarbitID.FARMING_TRANSMIT_E1,
		VarbitID.FARMING_TRANSMIT_E2,
		VarbitID.FARMING_TRANSMIT_F1,
		VarbitID.FARMING_TRANSMIT_F2);

	private static final Set<Integer> COMPOST_ITEMS = Set.of(
		ItemID.BUCKET_COMPOST,
		ItemID.BUCKET_SUPERCOMPOST,
		ItemID.BUCKET_ULTRACOMPOST,
		ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED);

	private static final Pattern COMPOST_APPLIED = Pattern.compile(
		"^You treat the .+ with (ultra|super)?compost\\.$",
		Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
	private static final Pattern FERTILE_SOIL_APPLIED = Pattern.compile(
		"^The .+ has been treated with (ultra|super)?compost.*$",
		Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
	private static final Pattern ALREADY_TREATED = Pattern.compile(
		"^This .+ has already been (?:treated|fertilised) with (ultra|super)?compost"
			+ "(?: - the spell can't make it any more fertile)?\\.?\\s*$",
		Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
	private static final Pattern INSPECTED_TREATED_SOIL = Pattern.compile(
		"^This is an? .+\\.\\s+The soil has been treated with (ultra|super)?compost\\..*",
		Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
	private static final Pattern[] COMPOST_MESSAGES = {
		COMPOST_APPLIED,
		FERTILE_SOIL_APPLIED,
		ALREADY_TREATED,
		INSPECTED_TREATED_SOIL
	};

	private final Map<GameObject, FarmingPatch> visiblePatches =
		new IdentityHashMap<>();
	private final Map<PatchKey, List<FarmingPatch>> patchGroups =
		new HashMap<>();
	private final Map<PatchKey, Set<PatchKey>> groupAliases =
		new HashMap<>();
	private final Map<PatchKey, CompostState> compostStates =
		new HashMap<>();
	private final Map<PatchKey, Long> stateVersions =
		new HashMap<>();
	private final Map<Integer, Boolean> farmableDefinitionCache = new HashMap<>();
	private final AtomicInteger lifecycleGeneration = new AtomicInteger();
	private final AtomicLong customSelectionGeneration = new AtomicLong();

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private SoilModelTint modelTint;

	@Inject
	private CompostStateStore compostStore;

	@Inject
	private ConfigManager configManager;

	@Inject
	private CompostedSoilConfig config;

	private volatile boolean active;
	private volatile boolean applyingPreset;
	private boolean groupsDirty;
	private long nextStateVersion;
	private double tintBrightness = Double.NaN;
	private PendingPatch pendingPatch;

	@Override
	protected void startUp()
	{
		active = true;
		cancelPendingCustomSelection();
		reconcilePresetSelection();
		int generation = lifecycleGeneration.incrementAndGet();
		clientThread.invoke(() ->
		{
			if (!isCurrentLifecycle(generation))
			{
				return;
			}

			clearAllState();
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				scanScene();
			}
		});
		log.debug("Composted Soil started");
	}

	@Override
	protected void shutDown()
	{
		active = false;
		cancelPendingCustomSelection();
		int generation = lifecycleGeneration.incrementAndGet();
		clientThread.invoke(() ->
		{
			if (lifecycleGeneration.get() == generation)
			{
				clearAllState();
			}
		});
		log.debug("Composted Soil stopped");
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		if (active)
		{
			registerPatch(event.getGameObject());
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		if (!active)
		{
			return;
		}

		FarmingPatch patch = visiblePatches.remove(event.getGameObject());
		if (patch != null)
		{
			patch.deactivateTint();
			groupsDirty = true;
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!active)
		{
			return;
		}

		if (!isPatchObservationAction(event))
		{
			return;
		}

		pendingPatch = null;
		ensureGroups();
		FarmingPatch patch = findTargetPatch(event);
		if (patch == null || patch.getKey() == null)
		{
			MenuEntry menuEntry = event.getMenuEntry();
			log.debug(
				"Could not resolve farming target id [{}], action [{}], scene [{}, {}], world view [{}]",
				event.getId(),
				event.getMenuAction(),
				event.getParam0(),
				event.getParam1(),
				menuEntry == null ? -1 : menuEntry.getWorldViewId());
			return;
		}

		pendingPatch =
			new PendingPatch(
				patch,
				Instant.now().plus(PENDING_TIMEOUT),
				configManager.getRSProfileKey());
		log.debug(
			"Captured pending compost observation for patch [{}]",
			patch.getKey());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!active
			|| event.getType() != ChatMessageType.GAMEMESSAGE
				&& event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		Instant now = Instant.now();
		expirePendingActions(now);
		ensureGroups();

		CompostState observed =
			compostStateFromMessage(event.getMessage());
		if (observed != null)
		{
			PendingPatch pending =
				takePending();
			if (pending != null)
			{
				setCompostState(
					currentKeyForPending(pending),
					observed);
			}
			else
			{
				log.debug(
					"Compost result [{}] had no matching pending patch",
					observed);
			}
			return;
		}

		if (isUntreatedMessage(event.getMessage()))
		{
			PendingPatch pending =
				takePending();
			if (pending != null)
			{
				setCompostState(
					currentKeyForPending(pending),
					CompostState.NONE);
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!active)
		{
			return;
		}

		ensureGroups();
		refreshTintsForBrightnessChange();
		expirePendingActions(Instant.now());

		List<FarmingPatch> changedPatches = new ArrayList<>();
		Set<PatchKey> completedCycles = new HashSet<>();
		for (FarmingPatch patch : visiblePatches.values())
		{
			ObjectComposition definition =
				currentDefinition(patch.getGameObject());
			int appearanceId = definition == null ? -1 : definition.getId();
			boolean appearanceChanged =
				patch.getAppearanceId() != appearanceId;
			patch.setAppearanceId(appearanceId);

			if (appearanceChanged)
			{
				changedPatches.add(patch);
			}

			PatchAppearance appearance =
				appearanceFrom(definition);
			if (patch.getAppearance().completesCycleWhen(appearance)
				&& patch.getKey() != null)
			{
				completedCycles.add(patch.getKey());
			}
			if (appearance != PatchAppearance.UNKNOWN)
			{
				patch.setAppearance(appearance);
			}
		}

		for (PatchKey key : completedCycles)
		{
			invalidateCompostState(key);
		}

		for (FarmingPatch patch : changedPatches)
		{
			refreshPatch(patch, true);
		}

		int tick = client.getTickCount();
		for (FarmingPatch patch : visiblePatches.values())
		{
			CompostState state =
				compostStates.get(patch.getKey());
			if (state != null
				&& state.isComposted()
				&& patch.canAttemptTint(tick))
			{
				attemptTint(patch, state);
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!active
			|| !CompostedSoilConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if (CompostedSoilConfig.PRESET.equals(event.getKey()))
		{
			cancelPendingCustomSelection();
			CompostedSoilPreset preset =
				presetFromValue(event.getNewValue());
			if (preset != null && preset != CompostedSoilPreset.CUSTOM)
			{
				applyPreset(preset);
			}
			else
			{
				rememberPresetSelection(preset);
			}
			return;
		}

		if (!isColorSetting(event.getKey()))
		{
			return;
		}

		if (shouldSwitchToCustom(
			applyingPreset,
			event.getKey(),
			config.preset(),
			config))
		{
			queueCustomSelection();
		}

		refreshVisiblePatches();
	}

	private void refreshVisiblePatches()
	{
		int generation = lifecycleGeneration.get();
		clientThread.invoke(() ->
		{
			if (!isCurrentLifecycle(generation))
			{
				return;
			}

			for (FarmingPatch patch : visiblePatches.values())
			{
				refreshPatch(patch, true);
			}
		});
	}

	static boolean isColorSetting(String key)
	{
		return CompostedSoilConfig.COMPOST_COLOR.equals(key)
			|| CompostedSoilConfig.SUPERCOMPOST_COLOR.equals(key)
			|| CompostedSoilConfig.ULTRACOMPOST_COLOR.equals(key);
	}

	private void reconcilePresetSelection()
	{
		CompostedSoilPreset preset = config.preset();
		if (preset != null
			&& preset != CompostedSoilPreset.CUSTOM
			&& !presetMatchesConfig(preset, config))
		{
			String previousPreset = configManager.getConfiguration(
				CompostedSoilConfig.GROUP,
				PRESET_STATE_KEY);
			if (shouldApplyMismatchedPreset(
				preset,
				previousPreset))
			{
				applyPreset(preset);
			}
			else
			{
				selectCustomPreset();
			}
			return;
		}
		rememberPresetSelection(preset);
	}

	private void applyPreset(CompostedSoilPreset preset)
	{
		Map<String, Object> settings = new LinkedHashMap<>();
		applyPreset(preset, settings::put);
		if (settings.isEmpty())
		{
			return;
		}

		boolean previouslyApplyingPreset = applyingPreset;
		applyingPreset = true;
		try
		{
			for (Map.Entry<String, Object> entry : settings.entrySet())
			{
				configManager.setConfiguration(
					CompostedSoilConfig.GROUP,
					entry.getKey(),
					entry.getValue());
			}
		}
		finally
		{
			applyingPreset = previouslyApplyingPreset;
		}
		CompostedSoilConfigPanelSync.refreshOpenPanel(settings);
		rememberPresetSelection(preset);
	}

	static void applyPreset(
		CompostedSoilPreset preset,
		BiConsumer<String, Object> settingWriter)
	{
		if (preset == null
			|| preset == CompostedSoilPreset.CUSTOM
			|| settingWriter == null)
		{
			return;
		}

		settingWriter.accept(
			CompostedSoilConfig.COMPOST_COLOR,
			preset.getCompostColor());
		settingWriter.accept(
			CompostedSoilConfig.SUPERCOMPOST_COLOR,
			preset.getSupercompostColor());
		settingWriter.accept(
			CompostedSoilConfig.ULTRACOMPOST_COLOR,
			preset.getUltracompostColor());
	}

	static boolean shouldSwitchToCustom(
		boolean applyingPreset,
		String key,
		CompostedSoilPreset selectedPreset,
		CompostedSoilConfig config)
	{
		return !applyingPreset
			&& isColorSetting(key)
			&& selectedPreset != null
			&& selectedPreset != CompostedSoilPreset.CUSTOM
			&& !presetMatchesConfig(selectedPreset, config);
	}

	static boolean presetMatchesConfig(
		CompostedSoilPreset preset,
		CompostedSoilConfig config)
	{
		return preset != null
			&& preset != CompostedSoilPreset.CUSTOM
			&& config != null
			&& Objects.equals(
				preset.getCompostColor(),
				config.compostColor())
			&& Objects.equals(
				preset.getSupercompostColor(),
				config.supercompostColor())
			&& Objects.equals(
				preset.getUltracompostColor(),
				config.ultracompostColor());
	}

	static CompostedSoilPreset presetFromValue(String value)
	{
		if (value == null)
		{
			return null;
		}

		for (CompostedSoilPreset preset : CompostedSoilPreset.values())
		{
			if (preset.toString().equals(value))
			{
				return preset;
			}
		}

		try
		{
			return CompostedSoilPreset.valueOf(value);
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
	}

	static boolean shouldApplyMismatchedPreset(
		CompostedSoilPreset selectedPreset,
		String previousPresetValue)
	{
		return selectedPreset != null
			&& selectedPreset != CompostedSoilPreset.CUSTOM
			&& selectedPreset != presetFromValue(previousPresetValue)
			&& previousPresetValue != null;
	}

	private void queueCustomSelection()
	{
		long generation;
		long configProfileId;
		synchronized (customSelectionGeneration)
		{
			generation = customSelectionGeneration.incrementAndGet();
			configProfileId = currentConfigProfileId();
		}

		SwingUtilities.invokeLater(() ->
		{
			synchronized (customSelectionGeneration)
			{
				if (!active
					|| configProfileId != currentConfigProfileId()
					|| !shouldApplyPendingCustomSelection(
						generation,
						customSelectionGeneration.get(),
						applyingPreset,
						config.preset()))
				{
					return;
				}

				selectCustomPreset();
			}
		});
	}

	private void selectCustomPreset()
	{
		configManager.setConfiguration(
			CompostedSoilConfig.GROUP,
			CompostedSoilConfig.PRESET,
			CompostedSoilPreset.CUSTOM.name());
		CompostedSoilConfigPanelSync.refreshOpenPanel(
			Collections.<String, Object>singletonMap(
				CompostedSoilConfig.PRESET,
				CompostedSoilPreset.CUSTOM.name()));
		rememberPresetSelection(CompostedSoilPreset.CUSTOM);
	}

	private void rememberPresetSelection(CompostedSoilPreset preset)
	{
		if (preset == null)
		{
			return;
		}

		String value = preset.name();
		if (!value.equals(configManager.getConfiguration(
			CompostedSoilConfig.GROUP,
			PRESET_STATE_KEY)))
		{
			configManager.setConfiguration(
				CompostedSoilConfig.GROUP,
				PRESET_STATE_KEY,
				value);
		}
	}

	private void cancelPendingCustomSelection()
	{
		synchronized (customSelectionGeneration)
		{
			customSelectionGeneration.incrementAndGet();
		}
	}

	private long currentConfigProfileId()
	{
		ConfigProfile profile = configManager.getProfile();
		return profile == null ? Long.MIN_VALUE : profile.getId();
	}

	static boolean shouldApplyPendingCustomSelection(
		long scheduledGeneration,
		long currentGeneration,
		boolean applyingPreset,
		CompostedSoilPreset selectedPreset)
	{
		return scheduledGeneration == currentGeneration
			&& !applyingPreset
			&& selectedPreset != null
			&& selectedPreset != CompostedSoilPreset.CUSTOM;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (!active)
		{
			return;
		}

		if (event.getGameState() == GameState.LOADING)
		{
			clearVisiblePatches();
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			scanScene();
		}
		else
		{
			clearAllState();
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		if (!active)
		{
			return;
		}

		cancelPendingCustomSelection();
		reconcilePresetSelection();
		refreshVisiblePatches();
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		if (!active)
		{
			return;
		}

		clearAllState();
		int generation = lifecycleGeneration.get();
		String expectedProfile = event.getNewProfile();
		clientThread.invokeLater(() ->
		{
			if (!isCurrentLifecycle(generation))
			{
				return;
			}

			if (Objects.equals(
				expectedProfile,
				configManager.getRSProfileKey())
				&& client.getGameState() == GameState.LOGGED_IN)
			{
				scanScene();
			}
		});
	}

	private boolean isCurrentLifecycle(int generation)
	{
		return active && lifecycleGeneration.get() == generation;
	}

	private void scanScene()
	{
		clearVisiblePatches();
		tintBrightness = modelTint.displayBrightness();
		WorldView worldView = client.getTopLevelWorldView();
		Scene scene = worldView == null ? null : worldView.getScene();
		if (scene == null)
		{
			return;
		}

		for (Tile[][] plane : scene.getTiles())
		{
			for (Tile[] column : plane)
			{
				for (Tile tile : column)
				{
					if (tile == null)
					{
						continue;
					}

					for (GameObject gameObject : tile.getGameObjects())
					{
						if (gameObject != null)
						{
							registerPatch(gameObject);
						}
					}
				}
			}
		}
		ensureGroups();
	}

	private FarmingPatch registerPatch(GameObject gameObject)
	{
		if (gameObject == null
			|| gameObject.getWorldView() == null
			|| !gameObject.getWorldView().isTopLevel())
		{
			return null;
		}

		FarmingPatch existing = visiblePatches.get(gameObject);
		if (existing != null)
		{
			return existing;
		}

		ObjectComposition baseDefinition =
			client.getObjectDefinition(gameObject.getId());
		if (!isFarmableRoot(baseDefinition))
		{
			return null;
		}

		int varbit = baseDefinition.getVarbitId();
		FarmingPatch patch =
			new FarmingPatch(gameObject, varbit);
		ObjectComposition definition = currentDefinition(gameObject);
		patch.setAppearanceId(definition == null ? -1 : definition.getId());
		patch.setAppearance(appearanceFrom(definition));
		visiblePatches.put(gameObject, patch);
		groupsDirty = true;
		return patch;
	}

	private boolean isFarmableRoot(ObjectComposition baseDefinition)
	{
		if (baseDefinition == null
			|| !FARMING_VARBITS.contains(baseDefinition.getVarbitId()))
		{
			return false;
		}

		Boolean cached = farmableDefinitionCache.get(baseDefinition.getId());
		if (cached != null)
		{
			return cached;
		}

		boolean farmable = isBareSoilDefinition(baseDefinition);
		int[] impostorIds = baseDefinition.getImpostorIds();
		if (impostorIds != null)
		{
			for (int impostorId : impostorIds)
			{
				if (impostorId >= 0
					&& isBareSoilDefinition(
						client.getObjectDefinition(impostorId)))
				{
					farmable = true;
					break;
				}
			}
		}

		farmableDefinitionCache.put(baseDefinition.getId(), farmable);
		return farmable;
	}

	private static boolean isBareSoilDefinition(
		ObjectComposition definition)
	{
		if (definition == null
			|| !hasAction(definition, "Inspect"))
		{
			return false;
		}

		String name = normalizedName(definition);
		return "allotment".equals(name)
			|| "coral nursery".equals(name)
			|| name.endsWith(" patch")
			|| hasAction(definition, "Rake");
	}

	private static PatchAppearance appearanceFrom(
		ObjectComposition definition)
	{
		if (definition == null)
		{
			return PatchAppearance.UNKNOWN;
		}
		return isBareSoilDefinition(definition)
			? PatchAppearance.BARE
			: PatchAppearance.PLANTED;
	}

	private static String normalizedName(ObjectComposition definition)
	{
		String name = definition == null ? null : definition.getName();
		return name == null ? "" : name.toLowerCase(Locale.ROOT);
	}

	private static boolean hasAction(
		ObjectComposition definition,
		String expected)
	{
		String[] actions = definition.getActions();
		if (actions == null)
		{
			return false;
		}

		for (String action : actions)
		{
			if (expected.equals(action))
			{
				return true;
			}
		}
		return false;
	}

	private ObjectComposition currentDefinition(GameObject gameObject)
	{
		ObjectComposition definition =
			client.getObjectDefinition(gameObject.getId());
		if (definition == null)
		{
			return null;
		}
		return definition.getImpostorIds() == null
			? definition
			: definition.getImpostor();
	}

	private void ensureGroups()
	{
		if (!groupsDirty)
		{
			return;
		}

		groupsDirty = false;
		patchGroups.clear();
		groupAliases.clear();
		Set<FarmingPatch> unvisited =
			java.util.Collections.newSetFromMap(new IdentityHashMap<>());
		unvisited.addAll(visiblePatches.values());

		while (!unvisited.isEmpty())
		{
			FarmingPatch seed = unvisited.iterator().next();
			List<FarmingPatch> component = new ArrayList<>();
			ArrayDeque<FarmingPatch> queue = new ArrayDeque<>();
			unvisited.remove(seed);
			queue.add(seed);
			while (!queue.isEmpty())
			{
				FarmingPatch current = queue.removeFirst();
				component.add(current);
				List<FarmingPatch> connected =
					new ArrayList<>();
				for (FarmingPatch candidate : unvisited)
				{
					if (current.connectsTo(candidate))
					{
						connected.add(candidate);
					}
				}
				for (FarmingPatch candidate : connected)
				{
					unvisited.remove(candidate);
					queue.addLast(candidate);
				}
			}

			PatchKey key = componentKey(component);
			Set<PatchKey> aliases = new HashSet<>();
			aliases.add(key);
			for (FarmingPatch patch : component)
			{
				aliases.add(memberKey(patch));
				aliases.addAll(patch.getKnownKeys());
			}

			List<PatchKey> orderedAliases =
				new ArrayList<>(aliases);
			orderedAliases.sort((left, right) ->
			{
				int comparison = Integer.compare(
					left.getWorldX(),
					right.getWorldX());
				if (comparison != 0)
				{
					return comparison;
				}
				comparison = Integer.compare(
					left.getWorldY(),
					right.getWorldY());
				if (comparison != 0)
				{
					return comparison;
				}
				comparison = Integer.compare(
					left.getPlane(),
					right.getPlane());
				return comparison != 0
					? comparison
					: Integer.compare(left.getVarbit(), right.getVarbit());
			});

			CompostState state = null;
			long stateVersion = -1L;
			for (PatchKey alias : orderedAliases)
			{
				long aliasVersion =
					stateVersions.getOrDefault(alias, -1L);
				CompostState aliasState =
					compostStates.get(alias);
				if (shouldReplaceState(
					aliasState,
					aliasVersion,
					state,
					stateVersion))
				{
					state = aliasState;
					stateVersion = aliasVersion;
				}
			}

			Map<PatchKey, CompostStateStore.StoredCompost> storedRecords =
				new HashMap<>();
			for (PatchKey alias : orderedAliases)
			{
				CompostStateStore
					.StoredCompost stored =
					compostStore.load(alias);
				storedRecords.put(alias, stored);
				if (stored.isValid()
					&& shouldReplaceState(
						stored.getState(),
						stored.getRevision(),
						state,
						stateVersion))
				{
					state = stored.getState();
					stateVersion = stored.getRevision();
				}
			}

			if (state != null)
			{
				nextStateVersion = Math.max(
					nextStateVersion,
					stateVersion);
				for (PatchKey alias : orderedAliases)
				{
					compostStates.put(alias, state);
					stateVersions.put(alias, stateVersion);
				}

				boolean needsBackfill = false;
				for (PatchKey alias : orderedAliases)
				{
					CompostStateStore.StoredCompost stored =
						storedRecords.get(alias);
					if (stored == null
						|| !stored.isValid()
						|| stored.getState() != state
						|| stored.getRevision() != stateVersion)
					{
						needsBackfill = true;
						break;
					}
				}
				if (needsBackfill)
				{
					compostStore.save(aliases, state, stateVersion);
				}
			}

			for (FarmingPatch patch : component)
			{
				patch.addKnownKeys(aliases);
				patch.setKey(key);
			}
			patchGroups
				.computeIfAbsent(key, ignored -> new ArrayList<>())
				.addAll(component);
			groupAliases
				.computeIfAbsent(key, ignored -> new HashSet<>())
				.addAll(aliases);
		}

		for (FarmingPatch patch : visiblePatches.values())
		{
			refreshPatch(patch, true);
		}
	}

	private static PatchKey memberKey(
		FarmingPatch patch)
	{
		WorldPoint location = patch.getCanonicalLocation();
		return new PatchKey(
			location.getX(),
			location.getY(),
			location.getPlane(),
			patch.getVarbit());
	}

	static boolean shouldReplaceState(
		CompostState candidateState,
		long candidateVersion,
		CompostState currentState,
		long currentVersion)
	{
		if (candidateState == null || candidateVersion < 0L)
		{
			return false;
		}
		if (currentState == null || candidateVersion > currentVersion)
		{
			return true;
		}
		return candidateVersion == currentVersion
			&& candidateState == CompostState.NONE
			&& currentState != CompostState.NONE;
	}

	private long nextStateRevision()
	{
		nextStateVersion = nextStateRevision(
			nextStateVersion,
			System.currentTimeMillis());
		return nextStateVersion;
	}

	static long nextStateRevision(long currentRevision, long now)
	{
		return Math.max(now, currentRevision + 1L);
	}

	private static PatchKey componentKey(
		List<FarmingPatch> component)
	{
		WorldPoint anchor = null;
		for (FarmingPatch patch : component)
		{
			WorldPoint candidate = patch.getCanonicalLocation();
			if (anchor == null || compareLocation(candidate, anchor) < 0)
			{
				anchor = candidate;
			}
		}

		return new PatchKey(
			anchor.getX(),
			anchor.getY(),
			anchor.getPlane(),
			component.get(0).getVarbit());
	}

	private static int compareLocation(WorldPoint left, WorldPoint right)
	{
		int comparison = Integer.compare(left.getX(), right.getX());
		if (comparison != 0)
		{
			return comparison;
		}
		comparison = Integer.compare(left.getY(), right.getY());
		return comparison != 0
			? comparison
			: Integer.compare(left.getPlane(), right.getPlane());
	}

	private boolean isPatchObservationAction(
		MenuOptionClicked event)
	{
		MenuAction action = event.getMenuAction();
		if (isGameObjectOption(action)
			&& "Inspect".equals(event.getMenuOption()))
		{
			return true;
		}

		if (!isWidgetTargetOnGameObject(action))
		{
			return false;
		}

		Widget selected = client.getSelectedWidget();
		if (selected == null)
		{
			return false;
		}

		return COMPOST_ITEMS.contains(selected.getItemId())
			|| selected.getId() == InterfaceID.MagicSpellbook.FERTILE_SOIL;
	}

	@SuppressWarnings("deprecation")
	private static boolean isWidgetTargetOnGameObject(MenuAction action)
	{
		return action == MenuAction.ITEM_USE_ON_GAME_OBJECT
			|| action == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT;
	}

	private static boolean isGameObjectOption(MenuAction action)
	{
		return action == MenuAction.GAME_OBJECT_FIRST_OPTION
			|| action == MenuAction.GAME_OBJECT_SECOND_OPTION
			|| action == MenuAction.GAME_OBJECT_THIRD_OPTION
			|| action == MenuAction.GAME_OBJECT_FOURTH_OPTION
			|| action == MenuAction.GAME_OBJECT_FIFTH_OPTION;
	}

	private FarmingPatch findTargetPatch(MenuOptionClicked event)
	{
		MenuEntry menuEntry = event.getMenuEntry();
		if (menuEntry == null)
		{
			return null;
		}

		WorldView worldView =
			client.getWorldView(menuEntry.getWorldViewId());
		if (worldView == null || !worldView.isTopLevel())
		{
			return null;
		}

		int targetVarbit = -1;
		ObjectComposition targetDefinition =
			client.getObjectDefinition(event.getId());
		if (targetDefinition != null
			&& FARMING_VARBITS.contains(targetDefinition.getVarbitId()))
		{
			targetVarbit = targetDefinition.getVarbitId();
		}

		int plane = worldView.getPlane();
		FarmingPatch patch = findTrackedPatch(
			worldView.getId(),
			plane,
			event.getParam0(),
			event.getParam1(),
			event.getId(),
			targetVarbit);
		if (patch != null)
		{
			return patch;
		}

		Scene scene = worldView.getScene();
		Tile[][][] tiles = scene == null ? null : scene.getTiles();
		int sceneX = event.getParam0();
		int sceneY = event.getParam1();
		if (tiles == null
			|| plane < 0
			|| plane >= tiles.length
			|| sceneX < 0
			|| sceneX >= tiles[plane].length
			|| sceneY < 0
			|| sceneY >= tiles[plane][sceneX].length)
		{
			return null;
		}

		Tile tile = tiles[plane][sceneX][sceneY];
		if (tile == null)
		{
			return null;
		}

		for (GameObject gameObject : tile.getGameObjects())
		{
			if (gameObject != null)
			{
				registerPatch(gameObject);
			}
		}
		ensureGroups();

		return findTrackedPatch(
			worldView.getId(),
			plane,
			sceneX,
			sceneY,
			event.getId(),
			targetVarbit);
	}

	private FarmingPatch findTrackedPatch(
		int worldViewId,
		int plane,
		int sceneX,
		int sceneY,
		int objectId,
		int targetVarbit)
	{
		FarmingPatch exact = null;
		FarmingPatch byVarbit = null;
		PatchKey exactKey = null;
		PatchKey varbitKey = null;
		boolean exactAmbiguous = false;
		boolean varbitAmbiguous = false;

		for (FarmingPatch patch : visiblePatches.values())
		{
			if (!patch.getFootprint().contains(
				worldViewId,
				plane,
				sceneX,
				sceneY))
			{
				continue;
			}

			if (patch.getGameObject().getId() == objectId)
			{
				if (exactKey != null && !exactKey.equals(patch.getKey()))
				{
					exactAmbiguous = true;
				}
				exact = patch;
				exactKey = patch.getKey();
			}
			if (targetVarbit >= 0 && patch.getVarbit() == targetVarbit)
			{
				if (varbitKey != null
					&& !varbitKey.equals(patch.getKey()))
				{
					varbitAmbiguous = true;
				}
				byVarbit = patch;
				varbitKey = patch.getKey();
			}
		}

		if (exact != null && !exactAmbiguous)
		{
			return exact;
		}
		return byVarbit != null && !varbitAmbiguous ? byVarbit : null;
	}

	private void setCompostState(
		PatchKey key,
		CompostState state)
	{
		ensureGroups();
		PatchKey currentKey = resolveCurrentKey(key);
		Set<PatchKey> aliases =
			groupAliases.get(currentKey);
		if (aliases == null)
		{
			aliases = java.util.Collections.singleton(currentKey);
		}

		long version = nextStateRevision();
		for (PatchKey alias : aliases)
		{
			compostStates.put(alias, state);
			stateVersions.put(alias, version);
		}
		compostStore.save(aliases, state, version);
		log.debug(
			"Confirmed compost state [{}] for patch [{}]",
			state,
			currentKey);

		List<FarmingPatch> patches = patchGroups.get(currentKey);
		if (patches != null)
		{
			for (FarmingPatch patch : patches)
			{
				refreshPatch(patch, true);
			}
		}
	}

	private void invalidateCompostState(PatchKey key)
	{
		ensureGroups();
		PatchKey currentKey = resolveCurrentKey(key);
		Set<PatchKey> aliases =
			groupAliases.get(currentKey);
		if (aliases == null)
		{
			aliases = java.util.Collections.singleton(currentKey);
		}

		boolean invalidated = false;
		long version = nextStateRevision();
		for (PatchKey alias : aliases)
		{
			CompostState previous =
				compostStates.put(
					alias,
					CompostState.NONE);
			invalidated |= previous != null && previous.isComposted();
			stateVersions.put(alias, version);
		}
		compostStore.save(
			aliases,
			CompostState.NONE,
			version);
		if (invalidated)
		{
			log.debug(
				"Cleared compost state after crop completion [{}]",
				currentKey);
		}

		List<FarmingPatch> patches = patchGroups.get(currentKey);
		if (patches != null)
		{
			for (FarmingPatch patch : patches)
			{
				refreshPatch(patch, true);
			}
		}
	}

	private PatchKey resolveCurrentKey(
		PatchKey key)
	{
		if (patchGroups.containsKey(key))
		{
			return key;
		}

		for (Map.Entry<
			PatchKey,
			Set<PatchKey>> entry : groupAliases.entrySet())
		{
			if (entry.getValue().contains(key))
			{
				return entry.getKey();
			}
		}
		return key;
	}

	static CompostState compostStateFromMessage(
		String message)
	{
		String cleaned = Text.removeTags(message == null ? "" : message);
		Matcher matcher = firstMatchingCompostMessage(cleaned);
		if (matcher == null)
		{
			return null;
		}

		String tier = matcher.group(1);
		if ("ultra".equalsIgnoreCase(tier))
		{
			return CompostState.ULTRACOMPOST;
		}
		if ("super".equalsIgnoreCase(tier))
		{
			return CompostState.SUPERCOMPOST;
		}
		return CompostState.COMPOST;
	}

	private static Matcher firstMatchingCompostMessage(String message)
	{
		for (Pattern pattern : COMPOST_MESSAGES)
		{
			Matcher matcher = pattern.matcher(message);
			if (matcher.matches())
			{
				return matcher;
			}
		}
		return null;
	}

	static boolean isUntreatedMessage(String message)
	{
		String cleaned = Text.removeTags(message == null ? "" : message)
			.toLowerCase(Locale.ROOT);
		return cleaned.contains("soil has not been treated")
			|| cleaned.contains("soil hasn't been treated");
	}

	static boolean isInspectedCompostMessage(String message)
	{
		String cleaned = Text.removeTags(message == null ? "" : message);
		return INSPECTED_TREATED_SOIL.matcher(cleaned).matches();
	}

	private void expirePendingActions(Instant now)
	{
		if (pendingPatch != null && pendingPatch.isExpired(now))
		{
			pendingPatch = null;
		}
	}

	private PendingPatch takePending()
	{
		PendingPatch pending = pendingPatch;
		if (pending == null)
		{
			return null;
		}

		pendingPatch = null;
		if (!Objects.equals(
			pending.profileKey,
			configManager.getRSProfileKey()))
		{
			log.debug(
				"Ignored compost result after RuneScape profile changed");
			return null;
		}

		return pending;
	}

	private PatchKey currentKeyForPending(
		PendingPatch pending)
	{
		for (FarmingPatch patch : visiblePatches.values())
		{
			if (patch.getVarbit() == pending.varbit
				&& patch.getCanonicalLocation().equals(
					pending.memberLocation))
			{
				return patch.getKey();
			}
		}
		return resolveCurrentKey(pending.key);
	}

	private void clearVisiblePatches()
	{
		for (FarmingPatch patch : visiblePatches.values())
		{
			patch.deactivateTint();
		}
		visiblePatches.clear();
		patchGroups.clear();
		groupAliases.clear();
		groupsDirty = false;
	}

	private void clearAllState()
	{
		clearVisiblePatches();
		compostStates.clear();
		stateVersions.clear();
		pendingPatch = null;
		farmableDefinitionCache.clear();
		nextStateVersion = 0L;
		tintBrightness = Double.NaN;
	}

	private void refreshTintsForBrightnessChange()
	{
		double currentBrightness = modelTint.displayBrightness();
		if (Double.compare(tintBrightness, currentBrightness) == 0)
		{
			return;
		}

		tintBrightness = currentBrightness;
		for (FarmingPatch patch : visiblePatches.values())
		{
			refreshPatch(patch, true);
		}
	}

	private void refreshPatch(
		FarmingPatch patch,
		boolean resetAttempts)
	{
		patch.deactivateTint();
		if (resetAttempts)
		{
			patch.resetTintAttempts();
		}

		CompostState state =
			compostStates.get(patch.getKey());
		if (state != null && state.isComposted())
		{
			attemptTint(patch, state);
		}
	}

	private void attemptTint(
		FarmingPatch patch,
		CompostState state)
	{
		int tick = client.getTickCount();
		if (!patch.canAttemptTint(tick))
		{
			return;
		}

		patch.recordTintAttempt(tick);
		patch.setSoilTint(
			modelTint.create(patch.getGameObject(), state));
	}

	@Provides
	CompostedSoilConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(CompostedSoilConfig.class);
	}

	private static final class PendingPatch
	{
		private final PatchKey key;
		private final Instant timeout;
		private final int varbit;
		private final WorldPoint memberLocation;
		private final String profileKey;

		private PendingPatch(
			FarmingPatch patch,
			Instant timeout,
			String profileKey)
		{
			this.key = patch.getKey();
			this.timeout = timeout;
			this.varbit = patch.getVarbit();
			this.memberLocation = patch.getCanonicalLocation();
			this.profileKey = profileKey;
		}

		private boolean isExpired(Instant now)
		{
			return !now.isBefore(timeout);
		}

	}
}

