package com.compostedsoil;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.GameObject;
import net.runelite.api.Point;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.WorldPoint;

final class FarmingPatch
{
	private static final int MAX_TINT_ATTEMPTS = 8;
	private static final int TINT_RETRY_DELAY_TICKS = 2;

	private final GameObject gameObject;
	private final int varbit;
	private final WorldPoint canonicalLocation;
	private final PatchFootprint footprint;
	private final Set<PatchKey> knownKeys = new HashSet<>();
	private PatchKey key;
	private RuneLiteObject soilTint;
	private int appearanceId;
	private PatchAppearance appearance =
		PatchAppearance.UNKNOWN;
	private int tintAttempts;
	private int nextTintAttemptTick;

	FarmingPatch(GameObject gameObject, int varbit)
	{
		this.gameObject = gameObject;
		this.varbit = varbit;
		WorldPoint canonical = WorldPoint.fromLocalInstance(
			gameObject.getWorldView().getScene(),
			gameObject.getLocalLocation(),
			gameObject.getPlane());
		this.canonicalLocation = canonical == null
			? gameObject.getWorldLocation()
			: canonical;

		Point min = gameObject.getSceneMinLocation();
		Point max = gameObject.getSceneMaxLocation();
		this.footprint = new PatchFootprint(
			gameObject.getWorldView().getId(),
			gameObject.getPlane(),
			min.getX(),
			min.getY(),
			max.getX(),
			max.getY());
	}

	GameObject getGameObject()
	{
		return gameObject;
	}

	PatchKey getKey()
	{
		return key;
	}

	void setKey(PatchKey key)
	{
		this.key = key;
		knownKeys.add(key);
	}

	void addKnownKeys(Set<PatchKey> keys)
	{
		knownKeys.addAll(keys);
	}

	Set<PatchKey> getKnownKeys()
	{
		return Collections.unmodifiableSet(knownKeys);
	}

	int getVarbit()
	{
		return varbit;
	}

	WorldPoint getCanonicalLocation()
	{
		return canonicalLocation;
	}

	PatchFootprint getFootprint()
	{
		return footprint;
	}

	boolean connectsTo(FarmingPatch other)
	{
		return varbit == other.varbit
			&& footprint.touches(other.footprint);
	}

	void setSoilTint(RuneLiteObject soilTint)
	{
		this.soilTint = soilTint;
	}

	void resetTintAttempts()
	{
		tintAttempts = 0;
		nextTintAttemptTick = 0;
	}

	boolean canAttemptTint(int tick)
	{
		return soilTint == null
			&& tintAttempts < MAX_TINT_ATTEMPTS
			&& tick >= nextTintAttemptTick;
	}

	void recordTintAttempt(int tick)
	{
		tintAttempts++;
		nextTintAttemptTick = tick + TINT_RETRY_DELAY_TICKS;
	}

	int getAppearanceId()
	{
		return appearanceId;
	}

	void setAppearanceId(int appearanceId)
	{
		this.appearanceId = appearanceId;
	}

	PatchAppearance getAppearance()
	{
		return appearance;
	}

	void setAppearance(PatchAppearance appearance)
	{
		this.appearance = appearance;
	}

	void deactivateTint()
	{
		if (soilTint != null)
		{
			soilTint.setActive(false);
			soilTint = null;
		}
	}
}

