package com.compostedsoil;

final class PatchFootprint
{
	private final int worldViewId;
	private final int plane;
	private final int minSceneX;
	private final int minSceneY;
	private final int maxSceneX;
	private final int maxSceneY;

	PatchFootprint(
		int worldViewId,
		int plane,
		int minSceneX,
		int minSceneY,
		int maxSceneX,
		int maxSceneY)
	{
		this.worldViewId = worldViewId;
		this.plane = plane;
		this.minSceneX = minSceneX;
		this.minSceneY = minSceneY;
		this.maxSceneX = maxSceneX;
		this.maxSceneY = maxSceneY;
	}

	boolean contains(
		int candidateWorldViewId,
		int candidatePlane,
		int sceneX,
		int sceneY)
	{
		return worldViewId == candidateWorldViewId
			&& plane == candidatePlane
			&& sceneX >= minSceneX
			&& sceneX <= maxSceneX
			&& sceneY >= minSceneY
			&& sceneY <= maxSceneY;
	}

	boolean touches(PatchFootprint other)
	{
		return worldViewId == other.worldViewId
			&& plane == other.plane
			&& minSceneX <= other.maxSceneX + 1
			&& maxSceneX + 1 >= other.minSceneX
			&& minSceneY <= other.maxSceneY + 1
			&& maxSceneY + 1 >= other.minSceneY;
	}

	int getWorldViewId()
	{
		return worldViewId;
	}

	int getPlane()
	{
		return plane;
	}

	int getMinSceneX()
	{
		return minSceneX;
	}

	int getMinSceneY()
	{
		return minSceneY;
	}

	int getMaxSceneX()
	{
		return maxSceneX;
	}

	int getMaxSceneY()
	{
		return maxSceneY;
	}
}

package com.compostedsoil;

import java.util.Objects;
final class PatchKey
{
	private static final String CONFIG_PREFIX = "patch";

	private final int worldX;
	private final int worldY;
	private final int plane;
	private final int varbit;

	PatchKey(
		int worldX,
		int worldY,
		int plane,
		int varbit)
	{
		this.worldX = worldX;
		this.worldY = worldY;
		this.plane = plane;
		this.varbit = varbit;
	}

	int getWorldX()
	{
		return worldX;
	}

	int getWorldY()
	{
		return worldY;
	}

	int getPlane()
	{
		return plane;
	}

	int getVarbit()
	{
		return varbit;
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof PatchKey))
		{
			return false;
		}

		PatchKey key = (PatchKey) other;
