package com.compostedsoil;

import java.awt.Color;
import java.util.Arrays;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.Perspective;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.TextureProvider;

@Slf4j
final class SoilModelTint
{
	private static final int SOIL_TILE_SPAN = 110;
	private static final int MODEL_SCALE_UNIT = 128;
	private static final int SOIL_LAYER_SEPARATION = 8;
	private static final int MAX_TINT_ALPHA = 0xbf;
	private static final int CANONICAL_PLANE_SCALE_PER_TILE = 149;
	private static final int CANONICAL_SOIL_PLANE_MODEL = 7766;

	private final Client client;
	private final CompostedSoilConfig config;

	@Inject
	SoilModelTint(
		Client client,
		CompostedSoilConfig config)
	{
		this.client = client;
		this.config = config;
	}

	RuneLiteObject create(
		GameObject gameObject,
		CompostState state)
	{
		Color color = configuredColor(state);
		if (color.getAlpha() == 0)
		{
			return null;
		}

		Model model = createCanonicalSoilPlane(
			gameObject,
			state,
			color.getRGB() & 0x00ffffff,
			color.getAlpha());
		if (model == null)
		{
			log.debug(
				"Could not create canonical soil plane for farming object [{}]",
				gameObject.getId());
			return null;
		}

		RuneLiteObject soilTint = client.createRuneLiteObject();
		soilTint.setModel(model);
		soilTint.setLocation(
			gameObject.getLocalLocation(),
			gameObject.getPlane());
		int tileZ = soilTint.getZ();
		int tintZ = tintWorldZ(tileZ);
		soilTint.setZ(tintZ);
		soilTint.setOrientation(0);
		soilTint.setRadius(Math.max(
			60,
			Math.max(gameObject.sizeX(), gameObject.sizeY())
				* Perspective.LOCAL_HALF_TILE_SIZE));
		soilTint.setActive(true);
		log.debug(
			"Created soil tint for object [{}], object Z [{}], tile Z [{}], tint Z [{}], size [{}x{}]",
			gameObject.getId(),
			gameObject.getZ(),
			tileZ,
			tintZ,
			gameObject.sizeX(),
			gameObject.sizeY());
		return soilTint;
	}

	private Model createCanonicalSoilPlane(
		GameObject gameObject,
		CompostState state,
		int targetRgb,
		int alpha)
	{
		ModelData source =
			client.loadModelData(CANONICAL_SOIL_PLANE_MODEL);
		if (!isCanonicalSoilPlane(source))
		{
			return null;
		}

		ModelData plane = source.shallowCopy()
			.cloneVertices()
			.cloneColors()
			.cloneTransparencies(true);
		short color = canonicalSoilHsl(
			targetRgb,
			displayBrightness(),
			state.getShadowContrast());
		Arrays.fill(plane.getFaceColors(), color);
		Arrays.fill(
			plane.getFaceTransparencies(),
			(byte) transparencyFromAlpha(alpha));
		plane = plane.scale(
			Math.max(1, gameObject.sizeX())
				* CANONICAL_PLANE_SCALE_PER_TILE,
			MODEL_SCALE_UNIT,
			Math.max(1, gameObject.sizeY())
				* CANONICAL_PLANE_SCALE_PER_TILE);
		return plane.light();
	}

	static boolean isCanonicalSoilPlane(ModelData model)
	{
		if (model == null
			|| model.getVerticesCount() != 4
			|| model.getFaceCount() != 2
			|| model.getFaceColors() == null
			|| model.getFaceColors().length < 2
			|| model.getFaceIndices1() == null
			|| model.getFaceIndices1().length < 2
			|| model.getFaceIndices2() == null
			|| model.getFaceIndices2().length < 2
			|| model.getFaceIndices3() == null
			|| model.getFaceIndices3().length < 2
			|| model.getFaceTextures() != null
				&& model.getFaceTextures().length < 2)
		{
			return false;
		}

		if (!isFlatSquarePlane(
			model.getVerticesX(),
			model.getVerticesY(),
			model.getVerticesZ(),
			model.getVerticesCount()))
		{
			return false;
		}

		boolean[] usedVertices = new boolean[model.getVerticesCount()];
		for (int face = 0; face < model.getFaceCount(); face++)
		{
			int a = model.getFaceIndices1()[face];
			int b = model.getFaceIndices2()[face];
			int c = model.getFaceIndices3()[face];
			if (!validVertex(
				a,
				model.getVerticesX(),
				model.getVerticesY(),
				model.getVerticesZ())
				|| !validVertex(
					b,
					model.getVerticesX(),
					model.getVerticesY(),
					model.getVerticesZ())
				|| !validVertex(
					c,
					model.getVerticesX(),
					model.getVerticesY(),
					model.getVerticesZ())
				|| signedProjectedArea(
					model.getVerticesX(),
					model.getVerticesZ(),
					a,
					b,
					c) <= 0.0d
				|| model.getFaceTextures() != null
					&& model.getFaceTextures()[face] != -1)
			{
				return false;
			}
			usedVertices[a] = true;
			usedVertices[b] = true;
			usedVertices[c] = true;
		}
		for (boolean used : usedVertices)
		{
			if (!used)
			{
				return false;
			}
		}
		return true;
	}

	static boolean isFlatSquarePlane(
		float[] verticesX,
		float[] verticesY,
		float[] verticesZ,
		int vertexCount)
	{
		if (verticesX == null
			|| verticesY == null
			|| verticesZ == null
			|| vertexCount != 4
			|| verticesX.length < vertexCount
			|| verticesY.length < vertexCount
			|| verticesZ.length < vertexCount)
		{
			return false;
		}

		float minimumX = Float.POSITIVE_INFINITY;
		float maximumX = Float.NEGATIVE_INFINITY;
		float minimumZ = Float.POSITIVE_INFINITY;
		float maximumZ = Float.NEGATIVE_INFINITY;
		float planeY = verticesY[0];
		for (int vertex = 0; vertex < vertexCount; vertex++)
		{
			if (Math.abs(verticesY[vertex] - planeY) > 0.001f)
			{
				return false;
			}
			minimumX = Math.min(minimumX, verticesX[vertex]);
			maximumX = Math.max(maximumX, verticesX[vertex]);
			minimumZ = Math.min(minimumZ, verticesZ[vertex]);
			maximumZ = Math.max(maximumZ, verticesZ[vertex]);
		}

		float spanX = maximumX - minimumX;
		float spanZ = maximumZ - minimumZ;
		return spanX >= SOIL_TILE_SPAN
			&& spanX <= SOIL_TILE_SPAN * 4
			&& Math.abs(spanX - spanZ) <= 1.0f;
	}

	static int transparencyFromAlpha(int alpha)
	{
		int clampedAlpha = clamp(alpha, 0, 255);
		if (clampedAlpha == 0)
		{
			return 255;
		}

		int tintAlpha = Math.max(
			1,
			Math.round(
				clampedAlpha * MAX_TINT_ALPHA / 255.0f));
		return Math.min(252, 255 - tintAlpha);
	}

	static short canonicalSoilHsl(
		int targetRgb,
		double brightness,
		double shadowContrast)
	{
		short target = targetHsl(targetRgb, brightness);
		int luminance = clamp(
			(int) Math.round(
				JagexColor.unpackLuminance(target)
					* (1.0d
						- Math.max(0.0d, Math.min(1.0d, shadowContrast))
							* 0.35d)),
			0,
			JagexColor.LUMINANCE_MAX);
		return JagexColor.packHSL(
			JagexColor.unpackHue(target),
			JagexColor.unpackSaturation(target),
			luminance);
	}

	static short targetHsl(int targetRgb, double brightness)
	{
		return JagexColor.rgbToHSL(
			0xff000000 | targetRgb,
			normalizeBrightness(brightness));
	}

	static int tintWorldZ(int sourceWorldZ)
	{
		return sourceWorldZ - SOIL_LAYER_SEPARATION;
	}

	double displayBrightness()
	{
		TextureProvider textureProvider = client.getTextureProvider();
		return normalizeBrightness(
			textureProvider == null
				? 1.0d
				: textureProvider.getBrightness());
	}

	private Color configuredColor(CompostState state)
	{
		switch (state)
		{
			case COMPOST:
				return config.compostColor();
			case SUPERCOMPOST:
				return config.supercompostColor();
			case ULTRACOMPOST:
				return config.ultracompostColor();
			default:
				return new Color(0, 0, 0, 0);
		}
	}

	private static double signedProjectedArea(
		float[] verticesX,
		float[] verticesZ,
		int a,
		int b,
		int c)
	{
		double abX = verticesX[b] - verticesX[a];
		double abZ = verticesZ[b] - verticesZ[a];
		double acX = verticesX[c] - verticesX[a];
		double acZ = verticesZ[c] - verticesZ[a];
		return abX * acZ - abZ * acX;
	}

	private static boolean validVertex(
		int vertex,
		float[] verticesX,
		float[] verticesY,
		float[] verticesZ)
	{
		return vertex >= 0
			&& vertex < verticesX.length
			&& vertex < verticesY.length
			&& vertex < verticesZ.length;
	}

	private static double normalizeBrightness(double brightness)
	{
		return Double.isFinite(brightness) && brightness > 0.0d
			? brightness
			: 1.0d;
	}

	private static int clamp(int value, int minimum, int maximum)
	{
		return Math.max(minimum, Math.min(maximum, value));
	}
}

package com.compostedsoil;

import java.util.LinkedHashSet;
import java.util.Set;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class CompostStateStoreTest
{
	private static final PatchKey FIRST =
		new PatchKey(3055, 3308, 0, 4773);
	private static final PatchKey SECOND =
		new PatchKey(3056, 3308, 0, 4773);

	@Test
	public void createsStableProfileKey()
	{
		assertEquals(
			"compoststate.v1.patch.3055.3308.0.4773",
			CompostStateStore.configKey(FIRST));
	}

	@Test
	public void parsesAllStatesIncludingNone()
	{
		for (CompostState state : CompostState.values())
		{
			CompostStateStore.StoredCompost stored =
				CompostStateStore.parse(
					"1|" + state.name() + "|42");
			assertTrue(stored.isPresent());
			assertTrue(stored.isValid());
			assertEquals(state, stored.getState());
			assertEquals(42L, stored.getRevision());
		}
	}

	@Test
	public void distinguishesMissingAndMalformedRecords()
	{
		CompostStateStore.StoredCompost missing =
			CompostStateStore.parse(null);
		assertFalse(missing.isPresent());
		assertFalse(missing.isValid());
		assertNull(missing.getState());

		for (String malformed : new String[]{
			"",
			"2|COMPOST|42",
			"1|UNKNOWN|42",
			"1|COMPOST|-1",
			"1|COMPOST|not-a-number"})
		{
			CompostStateStore.StoredCompost stored =
				CompostStateStore.parse(malformed);
			assertTrue(stored.isPresent());
			assertFalse(stored.isValid());
			assertNull(stored.getState());
		}
	}

	@Test
	public void savesIdenticalRecordForEveryPatchMember()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		when(configManager.getRSProfileKey()).thenReturn("profile-a");
		CompostStateStore store =
			new CompostStateStore(configManager);
		Set<PatchKey> aliases = new LinkedHashSet<>();
		aliases.add(FIRST);
		aliases.add(SECOND);

		store.save(aliases, CompostState.SUPERCOMPOST, 73L);

		verify(configManager).setRSProfileConfiguration(
			CompostedSoilConfig.GROUP,
			CompostStateStore.configKey(FIRST),
			"1|SUPERCOMPOST|73");
		verify(configManager).setRSProfileConfiguration(
			CompostedSoilConfig.GROUP,
			CompostStateStore.configKey(SECOND),
			"1|SUPERCOMPOST|73");
	}

	@Test
	public void savesNoneAsAnExplicitTombstone()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		when(configManager.getRSProfileKey()).thenReturn("profile-a");
		CompostStateStore store =
			new CompostStateStore(configManager);

		store.save(
			java.util.Collections.singleton(FIRST),
			CompostState.NONE,
			74L);

		verify(configManager).setRSProfileConfiguration(
			CompostedSoilConfig.GROUP,
			CompostStateStore.configKey(FIRST),
			"1|NONE|74");
	}

	@Test
	public void loadsOnlyFromActiveRuneScapeProfile()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		when(configManager.getRSProfileKey()).thenReturn("profile-a");
		when(configManager.getRSProfileConfiguration(
			CompostedSoilConfig.GROUP,
			CompostStateStore.configKey(FIRST)))
			.thenReturn("1|ULTRACOMPOST|99");
		CompostStateStore store =
			new CompostStateStore(configManager);

		CompostStateStore.StoredCompost stored = store.load(FIRST);

		assertTrue(stored.isValid());
		assertEquals(CompostState.ULTRACOMPOST, stored.getState());
		assertEquals(99L, stored.getRevision());
	}

	@Test
	public void doesNotReadOrWriteWithoutRuneScapeProfile()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		when(configManager.getRSProfileKey()).thenReturn(null);
		CompostStateStore store =
			new CompostStateStore(configManager);

		assertFalse(store.load(FIRST).isPresent());
		store.save(
			java.util.Collections.singleton(FIRST),
			CompostState.COMPOST,
			5L);

		verify(configManager, never()).getRSProfileConfiguration(
			CompostedSoilConfig.GROUP,
			CompostStateStore.configKey(FIRST));
		verify(configManager, never()).setRSProfileConfiguration(
			CompostedSoilConfig.GROUP,
			CompostStateStore.configKey(FIRST),
			"1|COMPOST|5");
	}
}

package com.compostedsoil;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class CompostStateTest
{
	@Test
	public void identifiesAppliedCompostTiers()
	{
		assertEquals(
			CompostState.COMPOST,
			CompostedSoilPlugin.compostStateFromMessage(
				"You treat the herb patch with compost."));
		assertEquals(
			CompostState.SUPERCOMPOST,
			CompostedSoilPlugin.compostStateFromMessage(
				"The herb patch has been treated with supercompost."));
		assertEquals(
			CompostState.ULTRACOMPOST,
			CompostedSoilPlugin.compostStateFromMessage(
				"This is a herb patch.\nThe soil has been treated with ultracompost."));
	}

	@Test
	public void identifiesAlreadyTreatedAndFertilisedMessages()
	{
		assertEquals(
			CompostState.SUPERCOMPOST,
			CompostedSoilPlugin.compostStateFromMessage(
				"This patch has already been treated with supercompost."));
		assertEquals(
			CompostState.COMPOST,
			CompostedSoilPlugin.compostStateFromMessage(
				"This herb patch has already been fertilised with compost"
					+ " - the spell can't make it any more fertile."));
	}

	@Test
	public void acceptsAlreadyTreatedMessageWithOptionalEnding()
	{
		assertEquals(
			CompostState.COMPOST,
			CompostedSoilPlugin.compostStateFromMessage(
				"This allotment has already been treated with compost"));
		assertEquals(
			CompostState.SUPERCOMPOST,
			CompostedSoilPlugin.compostStateFromMessage(
				"This allotment has already been treated with supercompost."));
		assertEquals(
			CompostState.ULTRACOMPOST,
			CompostedSoilPlugin.compostStateFromMessage(
				"This allotment has already been treated with ultracompost."
					+ "  \n\t"));
	}

	@Test
	public void ignoresUnrelatedCompostMessages()
	{
		assertNull(CompostedSoilPlugin.compostStateFromMessage(null));
		assertNull(CompostedSoilPlugin.compostStateFromMessage(
			"You put some compost in the compost bin."));
		assertNull(CompostedSoilPlugin.compostStateFromMessage(
			"The soil has not been treated."));
		assertNull(CompostedSoilPlugin.compostStateFromMessage(
			"You can't treat the herb patch with compost."));
		assertNull(CompostedSoilPlugin.compostStateFromMessage(
			"The soil has not been treated with compost."));
	}

	@Test
	public void removesFormattingAndIdentifiesInspectionMessages()
	{
		assertEquals(
			CompostState.COMPOST,
			CompostedSoilPlugin.compostStateFromMessage(
				"<col=0000ff>You treat the herb patch with compost.</col>"));
		assertTrue(CompostedSoilPlugin.isInspectedCompostMessage(
			"This is a herb patch.\n"
				+ "The soil has been treated with supercompost."));
		assertFalse(CompostedSoilPlugin.isInspectedCompostMessage(
			"You treat the herb patch with supercompost."));
	}

	@Test
	public void identifiesUntreatedInspection()
	{
		assertTrue(CompostedSoilPlugin.isUntreatedMessage(
			"This is a herb patch.\nThe soil has not been treated."));
		assertTrue(CompostedSoilPlugin.isUntreatedMessage(
			"The soil hasn't been treated."));
		assertFalse(CompostedSoilPlugin.isUntreatedMessage(
			"The soil has been treated with ultracompost."));
	}

	@Test
	public void usesDistinctDiegeticSoilMaterials()
	{
		assertEquals(0x341c00, CompostState.COMPOST.getRgb());
		assertEquals(0x1a2617, CompostState.SUPERCOMPOST.getRgb());
		assertEquals(0x3c1a1a, CompostState.ULTRACOMPOST.getRgb());
		assertEquals(
			0.0d,
			CompostState.COMPOST.getShadowContrast(),
			0.0d);
		assertEquals(
			0.30d,
			CompostState.SUPERCOMPOST.getShadowContrast(),
			0.0d);
		assertEquals(
			0.55d,
			CompostState.ULTRACOMPOST.getShadowContrast(),
			0.0d);
	}

	@Test
	public void newestStateWinsAndNoneWinsAnEqualRevision()
	{
		assertTrue(CompostedSoilPlugin.shouldReplaceState(
			CompostState.SUPERCOMPOST,
			11L,
			CompostState.COMPOST,
			10L));
		assertFalse(CompostedSoilPlugin.shouldReplaceState(
			CompostState.COMPOST,
			9L,
			CompostState.SUPERCOMPOST,
			10L));
		assertTrue(CompostedSoilPlugin.shouldReplaceState(
			CompostState.NONE,
			10L,
			CompostState.ULTRACOMPOST,
			10L));
		assertFalse(CompostedSoilPlugin.shouldReplaceState(
			CompostState.COMPOST,
			10L,
			CompostState.ULTRACOMPOST,
			10L));
	}

	@Test
	public void revisionsRemainMonotonicWhenClockDoesNotAdvance()
	{
		assertEquals(
			101L,
			CompostedSoilPlugin.nextStateRevision(100L, 100L));
		assertEquals(
			101L,
			CompostedSoilPlugin.nextStateRevision(100L, 50L));
		assertEquals(
			250L,
			CompostedSoilPlugin.nextStateRevision(100L, 250L));
	}
}

package com.compostedsoil;

import java.awt.Color;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.components.ColorJButton;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class CompostedSoilConfigPanelSyncTest
{
	@Test
	public void synchronizesPresetAndAllColors()
	{
		JPanel root = configPanel("Composted Soil");
		JComboBox<CompostedSoilPreset> preset =
			new JComboBox<>(CompostedSoilPreset.values());
		preset.setSelectedItem(CompostedSoilPreset.CUSTOM);
		row(root, "Preset", preset);

		ColorJButton compost =
			new ColorJButton("#FF000000", Color.BLACK);
		ColorJButton supercompost =
			new ColorJButton("#FF000000", Color.BLACK);
		ColorJButton ultracompost =
			new ColorJButton("#FF000000", Color.BLACK);
		row(root, "Compost color", compost);
		row(root, "Supercompost color", supercompost);
		row(root, "Ultracompost color", ultracompost);

		Map<String, Object> values = new LinkedHashMap<>();
		values.put(CompostedSoilConfig.PRESET, "RUINED_HEIR");
		CompostedSoilPlugin.applyPreset(
			CompostedSoilPreset.RUINED_HEIR,
			values::put);

		assertEquals(
			4,
			CompostedSoilConfigPanelSync.synchronize(root, values));
		assertSame(
			CompostedSoilPreset.RUINED_HEIR,
			preset.getSelectedItem());
		assertColor(
			CompostedSoilPreset.RUINED_HEIR.getCompostColor(),
			"#BF341C00",
			compost);
		assertColor(
			CompostedSoilPreset.RUINED_HEIR.getSupercompostColor(),
			"#BF1A2617",
			supercompost);
		assertColor(
			CompostedSoilPreset.RUINED_HEIR.getUltracompostColor(),
			"#BF3C1A1A",
			ultracompost);
	}

	@Test
	public void ignoresMatchingRowsOutsideThePluginPanel()
	{
		JPanel root = configPanel("Another plugin");
		JComboBox<CompostedSoilPreset> preset =
			new JComboBox<>(CompostedSoilPreset.values());
		preset.setSelectedItem(CompostedSoilPreset.RUINED_HEIR);
		row(root, "Preset", preset);
		row(
			root,
			"Compost color",
			new ColorJButton("#FF000000", Color.BLACK));
		row(
			root,
			"Supercompost color",
			new ColorJButton("#FF000000", Color.BLACK));
		row(
			root,
			"Ultracompost color",
			new ColorJButton("#FF000000", Color.BLACK));

		Map<String, Object> values = new LinkedHashMap<>();
		values.put(CompostedSoilConfig.PRESET, "CUSTOM");

		assertEquals(
			0,
			CompostedSoilConfigPanelSync.synchronize(root, values));
		assertSame(
			CompostedSoilPreset.RUINED_HEIR,
			preset.getSelectedItem());
	}

	@Test
	public void everyPresetFieldIsRegistered()
	{
		assertTrue(CompostedSoilConfigPanelSync.hasRegisteredField(
			CompostedSoilConfig.PRESET));
		assertTrue(CompostedSoilConfigPanelSync.hasRegisteredField(
			CompostedSoilConfig.COMPOST_COLOR));
		assertTrue(CompostedSoilConfigPanelSync.hasRegisteredField(
			CompostedSoilConfig.SUPERCOMPOST_COLOR));
		assertTrue(CompostedSoilConfigPanelSync.hasRegisteredField(
			CompostedSoilConfig.ULTRACOMPOST_COLOR));
		assertFalse(
			CompostedSoilConfigPanelSync.hasRegisteredField("unknown"));
	}

	private static JPanel configPanel(String title)
	{
		JPanel root = new JPanel();
		JPanel header = new JPanel();
		header.add(new JLabel(title));
		root.add(header);
		return root;
	}

	private static void row(
		JPanel root,
		String name,
		java.awt.Component control)
	{
		JPanel row = new JPanel();
		row.add(new JLabel(name));
		row.add(control);
		root.add(row);
	}

	private static void assertColor(
		Color expectedColor,
		String expectedText,
		ColorJButton button)
	{
		assertEquals(expectedColor, button.getColor());
		assertEquals(expectedText, button.getText());
	}
}

