import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class CompostedSoilPresetWorkflowTest
{
	@Test
	public void presetLabelsAndDefaultAreStable()
	{
		assertSame(
			CompostedSoilPreset.RUINED_HEIR,
			CompostedSoilPreset.DEFAULT);
		assertEquals(
			"Ruined Heir's preset",
			CompostedSoilPreset.RUINED_HEIR.toString());
		assertEquals("Custom", CompostedSoilPreset.CUSTOM.toString());
	}

	@Test
	public void selectingNamedPresetCopiesEveryColor()
	{
		Map<String, Object> settings = new LinkedHashMap<>();

		CompostedSoilPlugin.applyPreset(
			CompostedSoilPreset.RUINED_HEIR,
			settings::put);

		assertEquals(3, settings.size());
		assertEquals(
			new Color(0x34, 0x1c, 0x00, 0xbf),
			settings.get(CompostedSoilConfig.COMPOST_COLOR));
		assertEquals(
			new Color(0x1a, 0x26, 0x17, 0xbf),
			settings.get(CompostedSoilConfig.SUPERCOMPOST_COLOR));
		assertEquals(
			new Color(0x3c, 0x1a, 0x1a, 0xbf),
			settings.get(CompostedSoilConfig.ULTRACOMPOST_COLOR));
	}

	@Test
	public void customPresetDoesNotCopyColors()
	{
		Map<String, Object> settings = new LinkedHashMap<>();

		CompostedSoilPlugin.applyPreset(
			CompostedSoilPreset.CUSTOM,
			settings::put);

		assertTrue(settings.isEmpty());
	}

	@Test
	public void editingAnyColorSelectsCustomWhenValuesNoLongerMatch()
	{
		CompostedSoilConfig customized = new CompostedSoilConfig()
		{
			@Override
			public Color compostColor()
			{
				return Color.BLACK;
			}
		};

		assertTrue(CompostedSoilPlugin.shouldSwitchToCustom(
			false,
			CompostedSoilConfig.COMPOST_COLOR,
			CompostedSoilPreset.RUINED_HEIR,
			customized));
		assertTrue(CompostedSoilPlugin.shouldSwitchToCustom(
			false,
			CompostedSoilConfig.SUPERCOMPOST_COLOR,
			CompostedSoilPreset.RUINED_HEIR,
			customized));
		assertTrue(CompostedSoilPlugin.shouldSwitchToCustom(
			false,
			CompostedSoilConfig.ULTRACOMPOST_COLOR,
			CompostedSoilPreset.RUINED_HEIR,
			customized));
	}

	@Test
	public void presetWritesAndMatchingValuesStayNamed()
	{
		CompostedSoilConfig defaults = new CompostedSoilConfig()
		{
		};

		assertFalse(CompostedSoilPlugin.shouldSwitchToCustom(
			true,
			CompostedSoilConfig.COMPOST_COLOR,
			CompostedSoilPreset.RUINED_HEIR,
			defaults));
		assertFalse(CompostedSoilPlugin.shouldSwitchToCustom(
			false,
			CompostedSoilConfig.COMPOST_COLOR,
			CompostedSoilPreset.CUSTOM,
			defaults));
		assertFalse(CompostedSoilPlugin.shouldSwitchToCustom(
			false,
			"unrelated",
			CompostedSoilPreset.RUINED_HEIR,
			defaults));
		assertFalse(CompostedSoilPlugin.shouldSwitchToCustom(
			false,
			CompostedSoilConfig.COMPOST_COLOR,
			CompostedSoilPreset.RUINED_HEIR,
			defaults));
		assertTrue(CompostedSoilPlugin.presetMatchesConfig(
			CompostedSoilPreset.RUINED_HEIR,
			defaults));
	}

