	public void newerPresetSelectionCancelsPendingCustomSelection()
	{
		assertTrue(CompostedSoilPlugin.shouldApplyPendingCustomSelection(
			4,
			4,
			false,
			CompostedSoilPreset.RUINED_HEIR));
		assertFalse(CompostedSoilPlugin.shouldApplyPendingCustomSelection(
			4,
			5,
			false,
			CompostedSoilPreset.RUINED_HEIR));
		assertFalse(CompostedSoilPlugin.shouldApplyPendingCustomSelection(
			4,
			4,
			true,
			CompostedSoilPreset.RUINED_HEIR));
		assertFalse(CompostedSoilPlugin.shouldApplyPendingCustomSelection(
			4,
			4,
			false,
			CompostedSoilPreset.CUSTOM));
	}

