package com.compostedsoil;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PatchAppearanceTest
{
	@Test
	public void plantedToBareCompletesACompostCycle()
	{
		assertTrue(
			PatchAppearance.PLANTED.completesCycleWhen(
				PatchAppearance.BARE));
	}

	@Test
	public void noOtherAppearanceTransitionCompletesACompostCycle()
	{
		for (PatchAppearance previous :
			PatchAppearance.values())
		{
			for (PatchAppearance next :
				PatchAppearance.values())
			{
				if (previous == PatchAppearance.PLANTED
					&& next == PatchAppearance.BARE)
				{
					continue;
				}

				assertFalse(
					previous + " -> " + next,
					previous.completesCycleWhen(next));
			}
		}
	}
}

package com.compostedsoil;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PatchFootprintTest
{
	@Test
	public void containsInclusiveSceneBoundsInTheCorrectView()
	{
		PatchFootprint footprint =
			new PatchFootprint(3, 1, 10, 20, 14, 26);

		assertTrue(footprint.contains(3, 1, 10, 20));
		assertTrue(footprint.contains(3, 1, 14, 26));
		assertFalse(footprint.contains(3, 1, 9, 20));
		assertFalse(footprint.contains(3, 1, 15, 26));
		assertFalse(footprint.contains(4, 1, 10, 20));
		assertFalse(footprint.contains(3, 0, 10, 20));
	}

	@Test
	public void connectsTouchingTilesButNotSeparatedPlots()
	{
		PatchFootprint first =
			new PatchFootprint(3, 0, 10, 10, 12, 12);
		PatchFootprint touching =
			new PatchFootprint(3, 0, 13, 10, 15, 12);
		PatchFootprint separated =
			new PatchFootprint(3, 0, 14, 10, 16, 12);

		assertTrue(first.touches(touching));
		assertTrue(first.touches(
			new PatchFootprint(3, 0, 10, 13, 12, 15)));
		assertTrue(first.touches(
			new PatchFootprint(3, 0, 13, 13, 15, 15)));
		assertFalse(first.touches(separated));
		assertFalse(first.touches(
			new PatchFootprint(4, 0, 13, 10, 15, 12)));
		assertFalse(first.touches(
			new PatchFootprint(3, 1, 13, 10, 15, 12)));
	}

}

package com.compostedsoil;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

public class PatchKeyTest
{
	@Test
	public void describesTheFullCanonicalPatchIdentity()
	{
		PatchKey key =
			new PatchKey(2816, 3461, 0, 4774);

		assertEquals(2816, key.getWorldX());
		assertEquals(3461, key.getWorldY());
		assertEquals(0, key.getPlane());
		assertEquals(4774, key.getVarbit());
		assertEquals("patch.2816.3461.0.4774", key.toString());
	}

	@Test
	public void distinguishesEveryCanonicalPatchCoordinateAndVarbit()
	{
		PatchKey key =
			new PatchKey(2816, 3461, 0, 4774);

		assertEquals(
			key,
			new PatchKey(2816, 3461, 0, 4774));
		assertNotEquals(
			key,
			new PatchKey(2817, 3461, 0, 4774));
		assertNotEquals(
			key,
			new PatchKey(2816, 3462, 0, 4774));
		assertNotEquals(
			key,
			new PatchKey(2816, 3461, 1, 4774));
		assertNotEquals(
			key,
			new PatchKey(2816, 3461, 0, 4773));
	}
}

