public class SoilModelTintTest
{
	private static final int COMPOST_RGB = 0x341c00;

	@Test
	public void placesTintLayerEightUnitsAboveTerrain()
	{
		assertEquals(92, SoilModelTint.tintWorldZ(100));
		assertEquals(-8, SoilModelTint.tintWorldZ(0));
		assertTrue(SoilModelTint.tintWorldZ(100) < 100);
	}

	@Test
	public void rgbaAlphaControlsTranslucentTintStrength()
	{
		assertEquals(255, SoilModelTint.transparencyFromAlpha(0));
		assertEquals(252, SoilModelTint.transparencyFromAlpha(1));
		assertEquals(112, SoilModelTint.transparencyFromAlpha(0xbf));
		assertEquals(64, SoilModelTint.transparencyFromAlpha(0xff));
		assertEquals(255, SoilModelTint.transparencyFromAlpha(-1));
		assertEquals(64, SoilModelTint.transparencyFromAlpha(300));
	}

	@Test
	public void canonicalColorsUseConfiguredHueSaturationAndMaterialContrast()
	{
		assertCanonicalColor(CompostState.COMPOST, 13);
		assertCanonicalColor(CompostState.SUPERCOMPOST, 14);
		assertCanonicalColor(CompostState.ULTRACOMPOST, 18);
	}

	@Test
	public void canonicalColorClampsShadowContrast()
	{
		short target = SoilModelTint.targetHsl(COMPOST_RGB, 1.0d);
		short noContrast =
			SoilModelTint.canonicalSoilHsl(
				COMPOST_RGB,
				1.0d,
				-1.0d);
		short fullContrast =
			SoilModelTint.canonicalSoilHsl(
				COMPOST_RGB,
				1.0d,
				1.0d);
		short excessiveContrast =
			SoilModelTint.canonicalSoilHsl(
				COMPOST_RGB,
				1.0d,
				5.0d);

		assertEquals(
			JagexColor.unpackLuminance(target),
			JagexColor.unpackLuminance(noContrast));
		assertEquals(
			JagexColor.unpackLuminance(fullContrast),
			JagexColor.unpackLuminance(excessiveContrast));
		assertTrue(
			JagexColor.unpackLuminance(fullContrast)
				< JagexColor.unpackLuminance(noContrast));
	}

	@Test
	public void invalidBrightnessUsesNeutralEncoding()
	{
		short expected =
			SoilModelTint.targetHsl(COMPOST_RGB, 1.0d);

		assertEquals(
			expected,
			SoilModelTint.targetHsl(
				COMPOST_RGB,
				Double.NaN));
		assertEquals(
			expected,
			SoilModelTint.targetHsl(
				COMPOST_RGB,
				Double.POSITIVE_INFINITY));
		assertEquals(
			expected,
			SoilModelTint.targetHsl(COMPOST_RGB, 0.0d));
		assertEquals(
			expected,
			SoilModelTint.targetHsl(COMPOST_RGB, -1.0d));
	}

	@Test
	public void validatesCanonicalPlaneGeometry()
	{
		CanonicalPlane plane = new CanonicalPlane();

		assertTrue(
			SoilModelTint.isCanonicalSoilPlane(plane.data));
		assertTrue(
			SoilModelTint.isFlatSquarePlane(
				plane.verticesX,
				plane.verticesY,
				plane.verticesZ,
				4));
	}

	@Test
	public void rejectsSlopedRectangularAndUndersizedPlanes()
	{
		assertFalse(
			SoilModelTint.isFlatSquarePlane(
				new float[]{-55, 55, 55, -55},
				new float[]{0, 0, -8, 0},
				new float[]{-55, -55, 55, 55},
				4));
		assertFalse(
			SoilModelTint.isFlatSquarePlane(
				new float[]{-55, 55, 55, -55},
				new float[]{0, 0, 0, 0},
				new float[]{-32, -32, 32, 32},
				4));
		assertFalse(
			SoilModelTint.isFlatSquarePlane(
				new float[]{-32, 32, 32, -32},
				new float[]{0, 0, 0, 0},
				new float[]{-32, -32, 32, 32},
				4));
	}

	@Test
	public void rejectsBackFacingOrTexturedCanonicalPlane()
	{
		CanonicalPlane backFacing = new CanonicalPlane();
		when(backFacing.data.getFaceIndices2())
			.thenReturn(new int[]{2, 3});
		when(backFacing.data.getFaceIndices3())
			.thenReturn(new int[]{1, 2});
		assertFalse(
			SoilModelTint.isCanonicalSoilPlane(
				backFacing.data));

		CanonicalPlane textured = new CanonicalPlane();
		when(textured.data.getFaceTextures())
			.thenReturn(new short[]{-1, 4});
		assertFalse(
			SoilModelTint.isCanonicalSoilPlane(
				textured.data));
	}

	@Test
	public void everyPatchUsesOneCompleteCanonicalPlane()
	{
		Client client = mock(Client.class);
		CompostedSoilConfig config =
			mock(CompostedSoilConfig.class);
		TextureProvider textureProvider =
			mock(TextureProvider.class);
		CanonicalPlane plane = new CanonicalPlane();
		RuneLiteObject soilTint = mock(RuneLiteObject.class);
		GameObject patch = mock(GameObject.class);
		Color configured =
			new Color(0x34, 0x1c, 0x00, 0xbf);
		LocalPoint location = new LocalPoint(128, 128, 0);

		when(config.compostColor()).thenReturn(configured);
		when(client.getTextureProvider())
			.thenReturn(textureProvider);
		when(textureProvider.getBrightness()).thenReturn(1.0d);
		when(client.loadModelData(7766))
			.thenReturn(plane.data);
		when(client.createRuneLiteObject())
			.thenReturn(soilTint);
		when(patch.getLocalLocation()).thenReturn(location);
		when(patch.getPlane()).thenReturn(1);
		when(patch.sizeX()).thenReturn(2);
		when(patch.sizeY()).thenReturn(3);
		when(patch.getId()).thenReturn(8150);
		when(patch.getZ()).thenReturn(-264);
		when(soilTint.getZ()).thenReturn(-264);

		RuneLiteObject result =
			new SoilModelTint(client, config)
				.create(patch, CompostState.COMPOST);

		assertSame(soilTint, result);
		short expectedColor =
			SoilModelTint.canonicalSoilHsl(
				configured.getRGB() & 0x00ffffff,
				1.0d,
				CompostState.COMPOST.getShadowContrast());
		assertArrayEquals(
			new short[]{expectedColor, expectedColor},
			plane.faceColors);
		assertArrayEquals(
			new byte[]{112, 112},
			plane.faceTransparencies);
		verify(client).loadModelData(7766);
		verify(plane.data).shallowCopy();
		verify(plane.data).cloneVertices();
		verify(plane.data).cloneColors();
		verify(plane.data).cloneTransparencies(true);
		verify(plane.data).scale(298, 128, 447);
		verify(plane.data).light();
		verify(soilTint).setModel(plane.lit);
		verify(soilTint).setLocation(location, 1);
		verify(soilTint).setZ(-272);
		verify(soilTint).setOrientation(0);
		verify(soilTint).setRadius(192);
		verify(soilTint).setActive(true);
		verify(patch, never()).getRenderable();
		verify(patch, never()).getModelOrientation();
		verify(patch, never()).getOrientation();
	}

	@Test
	public void fullStrengthRemainsATranslucentLitTint()
	{
		Client client = mock(Client.class);
		CompostedSoilConfig config =
			mock(CompostedSoilConfig.class);
		CanonicalPlane plane = new CanonicalPlane();
		RuneLiteObject soilTint = mock(RuneLiteObject.class);
		GameObject patch = oneTilePatch();

		when(config.supercompostColor())
			.thenReturn(
				new Color(0x1a, 0x26, 0x17, 0xff));
		when(client.loadModelData(7766))
			.thenReturn(plane.data);
		when(client.createRuneLiteObject())
			.thenReturn(soilTint);

		assertSame(
			soilTint,
			new SoilModelTint(client, config)
				.create(
					patch,
					CompostState.SUPERCOMPOST));
		assertArrayEquals(
			new byte[]{64, 64},
			plane.faceTransparencies);
		verify(plane.data).scale(149, 128, 149);
		verify(plane.data).light();
		verify(soilTint).setModel(plane.lit);
	}

	@Test
	public void zeroAlphaAndUntreatedStateSkipAllRendering()
	{
		Client client = mock(Client.class);
		CompostedSoilConfig config =
			mock(CompostedSoilConfig.class);
		GameObject patch = mock(GameObject.class);
		when(config.compostColor())
			.thenReturn(new Color(0x34, 0x1c, 0x00, 0));

		SoilModelTint tint = new SoilModelTint(client, config);

		assertNull(
			tint.create(patch, CompostState.COMPOST));
		assertNull(
			tint.create(patch, CompostState.NONE));
		verify(client, never()).loadModelData(anyInt());
		verify(client, never()).createRuneLiteObject();
		verify(patch, never()).getRenderable();
	}

	@Test
	public void invalidCanonicalModelDoesNotCreateRuneLiteObject()
	{
		Client client = mock(Client.class);
		CompostedSoilConfig config =
			mock(CompostedSoilConfig.class);
		GameObject patch = mock(GameObject.class);
		when(config.ultracompostColor())
			.thenReturn(
				new Color(0x3c, 0x1a, 0x1a, 0xbf));
		when(patch.getId()).thenReturn(8151);

		assertNull(
			new SoilModelTint(client, config)
				.create(
					patch,
					CompostState.ULTRACOMPOST));
		verify(client).loadModelData(7766);
		verify(client, never()).createRuneLiteObject();
		verify(patch, never()).getRenderable();
	}

	@Test
	public void missingTextureProviderUsesNeutralBrightness()
	{
		Client client = mock(Client.class);
		CompostedSoilConfig config =
			mock(CompostedSoilConfig.class);

		assertEquals(
			1.0d,
			new SoilModelTint(client, config)
				.displayBrightness(),
			0.0d);
	}

	private static void assertCanonicalColor(
		CompostState state,
		int expectedLuminance)
	{
		short target =
			SoilModelTint.targetHsl(state.getRgb(), 1.0d);
		short actual =
			SoilModelTint.canonicalSoilHsl(
				state.getRgb(),
				1.0d,
				state.getShadowContrast());

		assertEquals(
			JagexColor.unpackHue(target),
			JagexColor.unpackHue(actual));
		assertEquals(
			JagexColor.unpackSaturation(target),
			JagexColor.unpackSaturation(actual));
		assertEquals(
			expectedLuminance,
			JagexColor.unpackLuminance(actual));
	}

	private static GameObject oneTilePatch()
	{
		GameObject patch = mock(GameObject.class);
		when(patch.getLocalLocation())
			.thenReturn(new LocalPoint(128, 128, 0));
		when(patch.sizeX()).thenReturn(1);
		when(patch.sizeY()).thenReturn(1);
		return patch;
	}

	private static final class CanonicalPlane
	{
		private final ModelData data = mock(ModelData.class);
		private final Model lit = mock(Model.class);
		private final float[] verticesX =
			{-55, 55, 55, -55};
		private final float[] verticesY = {0, 0, 0, 0};
		private final float[] verticesZ =
			{-55, -55, 55, 55};
		private final short[] faceColors = {0, 0};
		private final byte[] faceTransparencies = {
			(byte) 254,
			(byte) 254
		};

		private CanonicalPlane()
		{
			when(data.getVerticesCount()).thenReturn(4);
			when(data.getFaceCount()).thenReturn(2);
			when(data.getVerticesX()).thenReturn(verticesX);
			when(data.getVerticesY()).thenReturn(verticesY);
			when(data.getVerticesZ()).thenReturn(verticesZ);
			when(data.getFaceIndices1())
				.thenReturn(new int[]{0, 0});
			when(data.getFaceIndices2())
				.thenReturn(new int[]{1, 2});
			when(data.getFaceIndices3())
				.thenReturn(new int[]{2, 3});
			when(data.getFaceColors()).thenReturn(faceColors);
			when(data.getFaceTransparencies())
				.thenReturn(faceTransparencies);
			when(data.shallowCopy()).thenReturn(data);
			when(data.cloneVertices()).thenReturn(data);
			when(data.cloneColors()).thenReturn(data);
			when(data.cloneTransparencies(true))
				.thenReturn(data);
			when(data.scale(anyInt(), anyInt(), anyInt()))
				.thenReturn(data);
			when(data.light()).thenReturn(lit);
		}
	}
}
